-- CORPONOR | CARGA CONTROLADA EN govconor_resoluciones | MariaDB 10.6
-- 289 registros con fecha propuesta (no verificada contra PDF). SIEMPRE activo=0.
-- NO ejecutar antes de 01 y 02. NO ejecutar en producción sin respaldo y revisión.
-- Identificar manualmente un usuario administrador real: CAMBIAR 0 por el ID verificado.
SET @usuario_migracion_acuerdos := 0;
-- La siguiente condición detiene la ejecución antes de insertar cuando el usuario es inválido.
DROP PROCEDURE IF EXISTS validar_usuario_migracion_acuerdos;
DELIMITER $$
CREATE PROCEDURE validar_usuario_migracion_acuerdos()
BEGIN
 IF NOT EXISTS(SELECT 1 FROM usuarios WHERE id=@usuario_migracion_acuerdos AND activo=1 AND es_admin>=1) THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Debe configurar @usuario_migracion_acuerdos con un ID administrador activo real';
 END IF;
END$$
DELIMITER ;
CALL validar_usuario_migracion_acuerdos();
DROP PROCEDURE validar_usuario_migracion_acuerdos;
START TRANSACTION;
COMMIT;
-- Validaciones posteriores:
SELECT COUNT(*) AS registros_importados FROM acuerdos WHERE origen_post_id IS NOT NULL;
SELECT activo, COUNT(*) AS cantidad FROM acuerdos GROUP BY activo;
SELECT COUNT(*) AS sin_fecha_validada FROM mig_acuerdos_origen_revision WHERE fecha_sugerida IS NULL AND revision='OK_ORIGEN_CATEGORIA';
